def netting_triples(sizes, target):
    s = sorted(sizes)
    n = len(s)
    out = []
    for i in range(n - 2):
        if i and s[i] == s[i - 1]:
            continue
        lo, hi = i + 1, n - 1
        while lo < hi:
            total = s[i] + s[lo] + s[hi]
            if total < target:
                lo += 1
            elif total > target:
                hi -= 1
            else:
                out.append((s[i], s[lo], s[hi]))
                lo += 1
                hi -= 1
                while lo < hi and s[lo] == s[lo - 1]:
                    lo += 1
                while lo < hi and s[hi] == s[hi + 1]:
                    hi -= 1
    return out

